# Arkusze CKE z chemii w trybie „link + omówienie”:
# treść i materiały źródłowe zostają w oryginalnym PDF-ie CKE (link), w aplikacji są tylko:
# skrót polecenia, odpowiedź opracowana na podstawie zasad oceniania CKE i omówienie IndexLab.
CKE = 'https://cke.gov.pl/images/_EGZAMIN_MATURALNY_OD_2023/Arkusze_egzaminacyjne'
Z1 = '1 pkt – odpowiedź poprawna (zgodna z zasadami oceniania CKE).\n0 pkt – odpowiedź niepoprawna, niepełna lub brak odpowiedzi.'
ZR = 'Pełna punktacja tylko przy poprawnej metodzie, poprawnych obliczeniach i wyniku z jednostką (szczegóły: zasady oceniania CKE).'


def W(nr, strona, tytul, dzial, *zadania):
    return {'nr': nr, 'strona': strona, 'tytul': tytul,
            'zadania': [dict(z, dzialy=[dzial]) for z in zadania]}


def Z(nr, pkt, polecenie, odpowiedz, omowienie, zasady=None):
    return {'nr': nr, 'punkty': pkt, 'polecenie': polecenie, 'odpowiedz': odpowiedz,
            'zasady': zasady if zasady is not None else (Z1 if pkt == 1 else ZR), 'omowienie': omowienie}


